import numpy as np

cu, co = 4.0, 1.0  # lost margin per unit short, cost per unit left over
fractile = cu / (cu + co)
demand = np.array([8, 9, 10, 10, 11, 12, 12, 13, 15, 20])
order = np.quantile(demand, fractile, method="inverted_cdf")
print(f"critical fractile {fractile:.2f}, order quantity {order}")


def pinball(q, y, tau):
    return np.mean(np.maximum(tau * (y - q), (tau - 1) * (y - q)))


for q in (10, 13, 15):
    print(f"q={q}: pinball loss at tau 0.8 = {pinball(q, demand, 0.8):.3f}")

hit = {1: [1] * 19 + [0], 2: [1] * 17 + [0] * 3, 3: [1] * 12 + [0] * 8}
for h, v in hit.items():
    print(f"horizon {h}: 80% interval coverage {np.mean(v):.2f}")
print(f"pooled coverage {np.mean(sum(hit.values(), [])):.3f}")

import numpy as np

u = np.array([0.5, -0.2])
items = {"p": np.array([0.4, 0.1]), "n": np.array([-0.3, 0.6])}


def loss(u):
    s = u @ (items["p"] - items["n"])
    return np.log1p(np.exp(-s))


s = u @ (items["p"] - items["n"])
analytic = -(1 / (1 + np.exp(s))) * (items["p"] - items["n"])
h = 1e-6
numeric = np.array([(loss(u + h * e) - loss(u - h * e)) / (2 * h) for e in np.eye(2)])
print("score difference:", round(float(s), 4), " loss:", round(float(loss(u)), 6))
print("analytic grad:", analytic.round(6), " numeric grad:", numeric.round(6))

events = [("u1", "p", 1), ("u1", "q", 3), ("u1", "r", 6)]  # (user, item, day)
catalog = {"p", "q", "r", "s", "t"}
cutoff = 2
ever = {i for _, i, _ in events}
seen_by_cutoff = {i for _, i, day in events if day <= cutoff}
print("negatives if future is excluded:", sorted(catalog - ever))
print("negatives using only past positives:", sorted(catalog - seen_by_cutoff))
